class Forwarder extends PersistentActor with AtLeastOnceDelivery {
  override def persistenceId = "outbound-1"
  private var order = Vector.empty[Cmd]
  def receiveCommand = {
    case cmd: Cmd => persist(cmd) { e => order :+= e; deliver(peer)(id => Envelope(id, e)) }
    case Ack(id)  => confirmDelivery(id)
  }
  def receiveRecover = {
    case e: Cmd   => order :+= e
    case Ack(id)  => confirmDelivery(id)
  }
}

